// Marques propres à Lumen, sans équivalent Lucide. Même gabarit, pour se fondre
// dans le jeu système.
const LUMEN = {
  fluxo: '<circle cx="5" cy="6" r="2.2"/><circle cx="5" cy="18" r="2.2"/><circle cx="19" cy="12" r="2.2"/><path d="M7.1 6.8c4.4 1.1 6.6 2.7 9.6 4.5"/><path d="M7.1 17.2c4.4-1.1 6.6-2.7 9.6-4.5"/>',
};

/** Vrai si le nom est connu (Lucide, alias ou marque Lumen). */
export function hasIcon(name) {
  return Boolean(LUMEN[name] || LUCIDE[name] || LUCIDE[ALIAS[name]]);
}

/**
 * Icône d'interface, renvoyée en chaîne SVG prête à insérer.
 * `name` accepte un nom Lucide (« trash-2 ») ou un alias Lumen (« trash »).
 */
export function icon(name, opts = {}) {
  const stroke = opts.stroke ?? ICON_STROKE;
  const cls = opts.cls || "";
  const inner = LUMEN[name] || LUCIDE[name] || LUCIDE[ALIAS[name]];
  if (!inner) return "";
  return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="' + stroke
    + '" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"'
    + (cls ? ' class="' + cls + '"' : "") + ">" + inner + "</svg>";
}

/** Logo de marque (tracé plein, prend la couleur via currentColor). */
export function brandIcon(name, opts = {}) {
  const cls = opts.cls || "";
  const inner = BRAND[String(name || "").toLowerCase()];
  if (!inner) return "";
  return '<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true"'
    + (cls ? ' class="' + cls + '"' : "") + ">" + inner + "</svg>";
}

export { LUCIDE as _lucide, ALIAS as _alias, BRAND as _brand };
